          code: "/* E-R 图：学生(学号,姓名,系) --选修[m:n, 带属性 成绩]-- 课程(课程号,课程名,学分) */\n/* 第 1 步：实体成表（1:n 的方向在 student 里加外键，这里系直接作为属性） */\nCREATE TABLE student (\n  sno    CHAR(8)     PRIMARY KEY,          -- 实体的键\n  sname  VARCHAR(20) NOT NULL,\n  sdept  VARCHAR(20) NOT NULL\n);\n\nCREATE TABLE course (\n  cno     CHAR(6)     PRIMARY KEY,\n  cname   VARCHAR(40) NOT NULL,\n  credit  INT         NOT NULL CHECK (credit BETWEEN 1 AND 10),\n  tno     CHAR(6)                          -- 1:n 联系「教师—课程」: 1 端主键并到 n 端\n);\n\n/* 第 4 步：m:n 联系单建一张表，主键是双方主键的组合，联系属性 grade 落在表内 */\nCREATE TABLE sc (\n  sno    CHAR(8) NOT NULL,\n  cno    CHAR(6) NOT NULL,\n  grade  DECIMAL(4,1),                     -- 允许 NULL, 表示「已选未出分」\n  PRIMARY KEY (sno, cno),\n  FOREIGN KEY (sno) REFERENCES student(sno) ON DELETE CASCADE,\n  FOREIGN KEY (cno) REFERENCES course(cno)\n);\n\n/* 验证结构：插入几行数据 */\nINSERT INTO student VALUES ('S01','张伟','计算机'),('S02','李娜','计算机');\nINSERT INTO course  VALUES ('C01','数据库系统原理',4,'T01'),('C02','高等数学',5,'T02');\nINSERT INTO sc      VALUES ('S01','C01',92),('S01','C02',78),('S02','C01',88);\n\n/* 对照检查：这条查询能不能回答「谁选了数据库，考了多少分」 */\nSELECT s.sno, s.sname, c.cname, sc.grade\nFROM sc\nJOIN student s ON s.sno = sc.sno\nJOIN course  c ON c.cno = sc.cno\nWHERE c.cname = '数据库系统原理'\nORDER BY sc.grade DESC;\n-- 结果: S01|张伟|数据库系统原理|92.0\n--       S02|李娜|数据库系统原理|88.0",
