          code: "/* ============ DDL：建表与约束 ============ */\nCREATE TABLE customer (\n  cust_id   INTEGER     PRIMARY KEY,               -- 主键: 唯一且非空\n  cust_name VARCHAR(20) NOT NULL,\n  city      VARCHAR(20) NOT NULL,\n  reg_date  TEXT\n);\n\nCREATE TABLE orders (\n  order_id   INTEGER     PRIMARY KEY,\n  cust_id    INTEGER     NOT NULL REFERENCES customer(cust_id),  -- 外键: 参照完整性\n  amount     REAL        NOT NULL CHECK (amount >= 0),           -- CHECK: 用户定义完整性\n  status     TEXT        NOT NULL DEFAULT '待付款',\n  created_at TEXT        NOT NULL\n);\n\n/* ============ DML：插入数据 ============ */\nINSERT INTO customer VALUES\n  (1,'张伟','北京','2024-03-01'),(2,'李娜','上海','2024-05-12'),\n  (3,'王强','北京','2024-06-20'),(4,'赵敏','广州','2024-07-02'),\n  (5,'陈静','上海','2024-08-15');\nINSERT INTO orders VALUES\n  (1001,1,199.00,'已付款','2024-09-01'),(1002,1,89.50,'已付款','2024-09-02'),\n  (1003,2,1200.00,'待付款','2024-09-02'),(1004,3,45.00,'已取消','2024-09-03'),\n  (1005,2,300.00,'已付款','2024-09-04'),(1006,1,50.00,'待付款','2024-09-05'),\n  (1007,4,800.00,'已付款','2024-09-06');\n\n/* ============ DQL：单表查询（WHERE / ORDER BY / LIMIT） ============ */\n-- 1) 等值 + 范围 + 排序 + 截断\nSELECT order_id, amount, status FROM orders\nWHERE status = '已付款' AND amount >= 100\nORDER BY amount DESC, order_id ASC\nLIMIT 3;\n-- 结果: 1007|800.0|已付款   1005|300.0|已付款   1001|199.0|已付款\n\n-- 2) IN / BETWEEN / LIKE\nSELECT order_id FROM orders WHERE status IN ('已付款','待付款');\nSELECT order_id FROM orders WHERE amount BETWEEN 100 AND 300;   -- 含两端\nSELECT cust_name FROM customer WHERE cust_name LIKE '张%';      -- % 匹配任意长度\n\n/* ============ 聚合与分组：GROUP BY 之后才谈 HAVING ============ */\nSELECT c.city,\n       COUNT(*)        AS order_cnt,\n       SUM(o.amount)   AS total_amount,\n       ROUND(AVG(o.amount), 2) AS avg_amount\nFROM orders o\nJOIN customer c ON c.cust_id = o.cust_id\nWHERE o.status = '已付款'          -- 先按行过滤\nGROUP BY c.city                    -- 再分组\nHAVING SUM(o.amount) >= 100        -- 最后按组过滤\nORDER BY total_amount DESC;\n-- 结果: 广州|1|800.0|800.0\n--       上海|1|300.0|300.0\n--       北京|2|288.5|144.25\n\n/* ============ CASE WHEN：行内分支 ============ */\nSELECT order_id, amount,\n       CASE WHEN amount >= 1000 THEN '大额'\n            WHEN amount >= 100  THEN '中额'\n            ELSE '小额' END AS amount_band\nFROM orders ORDER BY order_id;",
