"INSERT INTO t VALUES(?)\", [(1,), (2,), (None,)])\ncur.execute(\"SELECT COUNT(*), COUNT(a), AVG(a) FROM t\")\nprint(\"Q4 COUNT(*), COUNT(a), AVG(a):\", cur.fetchone())   # (3, 2, 1.5)\ncur.execute(\"SELECT COUNT(*) FROM t WHERE a > 1 OR a <= 1\")\nprint(\"Q4 看似全覆盖的 OR，实际行数:\", cur.fetchone()[0])  # 2，NULL 行被丢掉\n\nconn.commit()\nconn.close()",
