          title: "用 SQL 亲手制造并解决四类并发异常（SQLite 双连接可复现）",
          code: "/* 场景：账户表，A 与 B 初始各 1000 元，总金额恒为 2000（这是不变量，用来检查一致性） */\nCREATE TABLE account (\n  acct_id INTEGER PRIMARY KEY,\n  owner   TEXT NOT NULL,\n  balance REAL NOT NULL CHECK (balance >= 0),\n  version INTEGER NOT NULL DEFAULT 0        -- 乐观锁版本号\n);\nINSERT INTO account(acct_id, owner, balance) VALUES (1,'A',1000),(2,'B',1000);\n\n/* ============ 1) 正确的事务：原子转账 ============ */\nBEGIN IMMEDIATE;                             -- 立即取写锁\nUPDATE account SET balance = balance - 100 WHERE acct_id = 1;\nUPDATE account SET balance = balance + 100 WHERE acct_id = 2;\nCOMMIT;                                      -- 要么两行都生效，要么都不生效\nSELECT SUM(balance) FROM account;            -- 恒为 2000\n\n/* ============ 2) 丢失修改的错误写法（自读自写，无锁） ============ */\n-- 应用层伪代码，两个连接同时执行：\n--   连接1: SELECT balance FROM account WHERE acct_id=1;   -- 读到 1000\n--   连接2: SELECT balance FROM account WHERE acct_id=1;   -- 也读到 1000\n--   连接1: UPDATE account SET balance = 1000 + 100 ...    -- 写回 1100\n--   连接2: UPDATE account SET balance = 1000 + 100 ...    -- 也写回 1100，覆盖了连接1\n-- 最终 1100，两笔各加 100 只生效一笔 → 丢失修改\n\n-- 正确写法一：把计算交给数据库，单条语句内原子完成\nUPDATE account SET balance = balance + 100 WHERE acct_id = 1;\n\n-- 正确写法二：悲观锁，先锁住再读\nBEGIN IMMEDIATE;\nSELECT balance FROM account WHERE acct_id = 1 FOR UPDATE;   -- MySQL/PostgreSQL 语法\nUPDATE account SET balance = balance + 100 WHERE acct_id = 1;\nCOMMIT;\n\n-- 正确写法三：乐观锁（版本号 CAS），冲突时影响行数为 0，由应用决定重试\nUPDATE account SET balance = balance + 100, version = version + 1\nWHERE acct_id = 1 AND version = 7;          -- 若已被别人改过，这里影响 0 行 → 重试\n\n/* ============ 3) 脏读场景（READ UNCOMMITTED 才可能） ============ */\n-- 连接1: BEGIN; UPDATE account SET balance=500 WHERE acct_id=1;   （未提交）\n-- 连接2: SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;\n--         SELECT balance FROM account WHERE acct_id=1;   -- 读到 500（脏读）\n-- 连接1: ROLLBACK;                                        -- A 回到 1000\n-- 连接2 此前据 500 做的任何决策都是错的\n\n/* ============ 4) 不可重复读（READ COMMITTED 允许） ============ */\n-- 连接1: BEGIN; SELECT balance FROM account WHERE acct_id=1;   -- 1000\n-- 连接2: UPDATE account SET balance=1200 WHERE acct_id=1; COMMIT;\n-- 连接1: SELECT balance FROM account WHERE acct_id=1;          -- 1200 ≠ 1000，不可重复读\n\n/* ============ 5) 幻读（针对新插入的行） ============ */\n-- 连接1: BEGIN; SELECT COUNT(*) FROM orders WHERE amount > 500;  -- 1 行\n-- 连接2: INSERT INTO orders VALUES(1008, 2, 900.0, '已付款', '2024-09-07'); COMMIT;\n-- 连接1: SELECT COUNT(*) FROM orders WHERE amount > 500;         -- 2 行，出现了幻影行\n-- InnoDB 在 REPEATABLE READ 下靠 MVCC 快照读避免了这个现象（第二次仍读快照）\n\n/* ============ 6) 隔离级别设置（MySQL 语法，会话级） ============ */\nSET SESSION TRANSACTION ISOLATION LEVEL READ COMMITTED;\nSELECT @@transaction_isolation;              -- 查询当前隔离级别\nSET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;\n\n/* ============ 7) 观察锁等待：开两个连接各执行一遍 ============ */\n-- 连接1: BEGIN; UPDATE account SET balance=balance-1 WHERE acct_id=1;  （持有行锁）\n-- 连接2: UPDATE account SET balance=balance-1 WHERE acct_id=1;        （阻塞，等待锁）\n-- MySQL 里查锁等待：\nSELECT * FROM performance_schema.data_lock_waits;            -- 谁在等谁\nSELECT trx_id, trx_state, trx_started FROM information_schema.innodb_trx;  -- 活跃事务\n\n/* ============ 8) 长事务的反面教材：旧版本无法清理 ============ */\nBEGIN;\nSELECT * FROM orders LIMIT 1;      -- 建立快照后长时间不提交\n-- 此后所有被修改行的旧版本都必须保留（供这个事务的 MVCC 读），undo 表空间持续膨胀\n-- 工程结论：事务要短，读操作不要在事务里做网络调用或等用户输入\nROLLBACK;",
