          title: "完整案例：图书借阅系统从 E-R 到建表到索引",
          code: "/* ============================================================\n   案例：图书借阅系统\n   需求（第 1 阶段·需求分析，摘出关键业务规则）：\n     R1 一个读者可以有多个借书证，一张借书证只属于一个读者\n     R2 一本书（书目）可以有多个副本（馆藏册），一个副本只属于一个书目\n     R3 一个读者可以借多个副本，一个副本同一时刻最多被一个读者借走\n     R4 借阅记录要有借出日期、应还日期、实还日期，用于计算逾期\n     R5 图书分类是多层的（如 计算机 > 数据库）\n\n   概念设计（第 2 阶段·E-R）：\n     reader(读者) --1:n-- card(借书证) --1:n-- loan(借阅) --n:1-- copy(副本) --n:1-- book(书目)\n     book --n:1-- category(分类，自联系 n:1 表示上级分类)\n\n   逻辑设计（第 3 阶段·转关系模式 + 规范化）：\n     实体：reader, book, category         → 3 张表\n     1:n 联系：card.reader_id, copy.book_id, loan.card_id/copy_id,\n              category.parent_id         → 不新增表，靠外键\n     m:n 联系：无（借阅被建模为实体 loan，这在有属性、有生命周期时更合适）\n   ============================================================ */\n\n/* ============ 第 4 阶段·物理设计：建表 ============ */\nCREATE TABLE reader (\n  reader_id   INTEGER PRIMARY KEY,\n  reader_name VARCHAR(20) NOT NULL,\n  reader_type TEXT NOT NULL DEFAULT '学生' CHECK (reader_type IN ('学生','教师','校外')),\n  phone       VARCHAR(20),\n  reg_date    TEXT NOT NULL\n);\n\nCREATE TABLE category (\n  cate_id   INTEGER PRIMARY KEY,\n  cate_name VARCHAR(30) NOT NULL,\n  parent_id INTEGER REFERENCES category(cate_id)   -- 自联系: 分类树\n);\n\nCREATE TABLE book (\n  book_id   INTEGER PRIMARY KEY,\n  isbn      VARCHAR(20) NOT NULL UNIQUE,\n  title     VARCHAR(100) NOT NULL,\n  author    VARCHAR(50),\n  cate_id   INTEGER NOT NULL REFERENCES category(cate_id),\n  price     DECIMAL(8,2) CHECK (price >= 0)       -- 金额用 DECIMAL 不用 FLOAT\n);\n\nCREATE TABLE copy (                               -- 馆藏册: 同一书目可有多本\n  copy_id  INTEGER PRIMARY KEY,\n  book_id  INTEGER NOT NULL REFERENCES book(book_id),\n  location TEXT NOT NULL,                         -- 馆藏位置\n  status   TEXT NOT NULL DEFAULT '在架' CHECK (status IN ('在架','借出','遗失','维修'))\n);\n\nCREATE TABLE card (\n  card_id   INTEGER PRIMARY KEY,\n  reader_id INTEGER NOT NULL REFERENCES reader(reader_id),\n  issue_date TEXT NOT NULL,\n  status    TEXT NOT NULL DEFAULT '正常' CHECK (status IN ('正常','挂失','注销'))\n);\n\nCREATE TABLE loan (\n  loan_id    INTEGER PRIMARY KEY,\n  card_id    INTEGER NOT NULL REFERENCES card(card_id),\n  copy_id    INTEGER NOT NULL REFERENCES copy(copy_id),\n  loan_date  TEXT NOT NULL,\n  due_date   TEXT NOT NULL,\n  return_date TEXT,                               -- NULL 表示尚未归还\n  CHECK (due_date >= loan_date)\n);\n\n/* ============ 物理设计·索引: 每个索引都对应一个真实查询 ============ */\n-- 索引 1: 「某读者的所有借阅」——高频，且选择率高（读者很多，每人借阅少）\nCREATE INDEX idx_loan_card ON loan(card_id, loan_date);\n\n-- 索引 2: 「某副本当前是否被借出」——用于借书时的可用性检查\nCREATE INDEX idx_loan_copy ON loan(copy_id);\n\n-- 索引 3: 「按分类查书目」——等值 + 排序，联合索引让 ORDER BY 免排序\nCREATE INDEX idx_book_cate_title ON book(cate_id, title);\n\n-- 索引 4: 逾期清单——只关心未归还的，用部分索引（只索引需要的行，索引更小）\nCREATE INDEX idx_loan_overdue ON loan(due_date) WHERE return_date IS NULL;\n\n/* ============ 验证设计：三个真实查询 ============ */\n-- Q1 某个读者当前借了哪些书（含书名与应还日期）\nSELECT l.loan_id, b.title, l.loan_date, l.due_date\nFROM loan l\nJOIN copy  c ON c.copy_id  = l.copy_id\nJOIN book  b ON b.book_id  = c.book_id\nJOIN card  cd ON cd.card_id = l.card_id\nWHERE cd.reader_id = 1 AND l.return_date IS NULL\nORDER BY l.due_date;\n\n-- Q2 逾期未还清单（逾期天数用日期差计算）\nSELECT l.loan_id, b.title, l.due_date,\n       CAST(julianday('2024-09-30') - julianday(l.due_date) AS INTEGER) AS overdue_days\nFROM loan l JOIN copy c ON c.copy_id=l.copy_id JOIN book b ON b.book_id=c.book_id\nWHERE l.return_date IS NULL AND l.due_date < '2024-09-30'\nORDER BY overdue_days DESC;\n\n-- Q3 每个分类下的书目数量（含没有书目的分类，用 LEFT JOIN 保底）\nSELECT ca.cate_name, COUNT(b.book_id) AS book_cnt\nFROM category ca LEFT JOIN book b ON b.cate_id = ca.cate_id\nGROUP BY ca.cate_id ORDER BY book_cnt DESC;\n\n/* ============ 借书事务：检查可用 + 写借阅 + 改副本状态，必须原子 ============ */\nBEGIN IMMEDIATE;\nUPDATE copy SET status='借出' WHERE copy_id=101 AND status='在架';\n-- 若上面影响 0 行说明副本已被别人借走，应用应回滚并提示\nINSERT INTO loan(loan_id, card_id, copy_id, loan_date, due_date)\nVALUES (5001, 1, 101, '2024-09-10', '2024-10-10');\nCOMMIT;",
