          title: "大表优化的三种手段：读写分离、分库分表、缓存旁路（伪代码 + 可运行片段）",
          code: "# 说明：分库分表与读写分离依赖具体中间件，这里给出「应用层要做什么」的可运行骨架。\n\n# ---------- 1) 读写分离：写主库、读从库（伪代码结构，可直接套用 DB-API） ----------\nimport sqlite3, hashlib\n\nclass ReadWriteSplit:\n    def __init__(self, primary_dsn, replica_dsns):\n        self.primary = primary_dsn\n        self.replicas = replica_dsns\n\n        def _pick_replica(self, key):\n            # 同一用户的读尽量落到同一从库，减少「刚写完立刻读却读不到」的概率\n            idx = int(hashlib.md5(str(key).encode()).hexdigest(), 16) % len(self.replicas)\n            return self.replicas[idx]\n\n            def write(self, sql, params=()):\n                conn = sqlite3.connect(self.primary)\n                try:\n                    cur = conn.execute(sql, params)\n                    conn.commit()\n                    return cur.rowcount\n                finally:\n                    conn.close()\n\n                    def read(self, sql, params=(), key=None):\n                        conn = sqlite3.connect(self._pick_replica(key))\n                        try:\n                            return conn.execute(sql, params).fetchall()\n                        finally:\n                            conn.close()\n\n                            # 关键认知：主从复制是**异步**的，所以「写后立刻读」可能读到旧数据（复制延迟）。\n                            # 解决办法：写后一段时间内的读强制走主库（read-your-writes 会话一致性）。\n\n                            # ---------- 2) 分库分表：水平切分的路由与跨片查询代价 ----------\n                            def shard_of(user_id, shard_count=4):\n                                \"\"\"按 user_id 取模路由到某张分片表 orders_0..orders_3\"\"\"\n                                return user_id % shard_count\n\n                                def table_name(user_id):\n                                    return \"orders_%d\" % shard_of(user_id)\n\n                                    print(table_name(1001), table_name(1002), table_name(1003), table_name(1004))\n                                    # 1001 -> orders_1，1002 -> orders_2，1003 -> orders_3，1004 -> orders_0\n\n                                    # 分片带来的三个新问题，必须提前想清楚：\n                                    #   a) 跨片查询：SELECT COUNT(*) 要合并 4 个分片的结果（ scatter-gather ）\n                                    #   b) 分布式事务：同一笔业务若跨片写入，需要 2PC/TCC/Saga 或「按业务主体分片」来规避\n                                    #   c) 全局唯一 ID：不能再用单库自增，需要雪花算法（Snowflake）或号段模式\n\n                                    # ---------- 3) 缓存旁路（cache-aside）：最常见的读优化 ----------\n                                    cache = {}\n\n                                    def get_order(conn, order_id):\n                                        if order_id in cache:                      # 1) 先查缓存\n                                            return cache[order_id]\n                                            row = conn.execute(\"SELECT * FROM orders WHERE order_id=?\", (order_id,)).fetchone()\n                                            if row:                                    # 2) 未命中则查库\n                                                cache[order_id] = row                  # 3) 回填缓存\n                                                return row\n\n                                                def update_order(conn, order_id, amount):\n                                                    conn.execute(\"UPDATE orders SET amount=? WHERE order_id=?\", (amount, order_id))\n                                                    conn.commit()\n                                                    cache.pop(order_id, None)                  # 4) 失效而不是更新，避免并发写导致的脏缓存\n                                                    # 注意：先更新数据库再删缓存，且删除失败要重试；不要「先删缓存再更新库」\n\n                                                    # ---------- 4) 一个自测：验证分片路由是稳定的 ----------\n                                                    assert shard_of(1001) == 1 and shard_of(1002) == 2\n                                                    assert shard_of(1003) == 3 and shard_of(1004) == 0\n                                                    print(\"分片路由自测通过；同一 user_id 永远落到同一分片\")",
